import os, json
PAIRS = [["/* ================= save ================= */", "/* ================= native shell (Capacitor) =================\n   Active only inside the store app (Android/iOS). On the website nothing here runs. */\nconst NATIVE=!!(window.Capacitor&&Capacitor.isNativePlatform&&Capacitor.isNativePlatform());\nconst CP=NATIVE&&Capacitor.Plugins?Capacitor.Plugins:{};\nfunction nativeCall(fn){try{const r=fn();if(r&&r.catch)r.catch(()=>{})}catch(e){}}\n\n/* ================= save ================= */", 1], ["function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(SV))}catch(e){}}", "function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(SV))}catch(e){}if(NATIVE&&CP.Preferences)nativeCall(()=>CP.Preferences.set({key:SAVE_KEY,value:JSON.stringify(SV)}))}\nif(NATIVE&&CP.Preferences){try{if(!localStorage.getItem(SAVE_KEY))nativeCall(()=>CP.Preferences.get({key:SAVE_KEY}).then(r=>{if(r&&r.value){localStorage.setItem(SAVE_KEY,r.value);location.reload()}}))}catch(e){}}", 1], ["function vib(p){try{navigator.vibrate&&navigator.vibrate(p)}catch(e){}}", "function vib(p){try{if(NATIVE&&CP.Haptics){const ms=Array.isArray(p)?p.reduce((a,b,i)=>i%2?a:a+b,0):p;if(ms<=25)nativeCall(()=>CP.Haptics.impact({style:'LIGHT'}));else nativeCall(()=>CP.Haptics.vibrate({duration:Math.min(400,ms)}))}else navigator.vibrate&&navigator.vibrate(p)}catch(e){}}", 1], ["const PLAT=location.protocol==='file:'?'apk':", "const PLAT=NATIVE?Capacitor.getPlatform():location.protocol==='file:'?'apk':", 1], ["renderMenu();\nloadSkin();\n", "renderMenu();\nloadSkin();\nif(NATIVE){\n  if(CP.StatusBar)nativeCall(()=>CP.StatusBar.hide());\n  if(CP.SplashScreen)nativeCall(()=>CP.SplashScreen.hide());\n  if(CP.App)nativeCall(()=>CP.App.addListener('backButton',()=>{\n    const open=['#ovHelp','#ovPause'].find(s=>!$(s).hidden);\n    if(open==='#ovHelp'){$('#helpOk').click();return}\n    if(open==='#ovPause'){$('#ovPause').hidden=true;showMenu();return}\n    if(S&&S.state==='play'){$('#pauseBtn').click();return}\n    if(S){showMenu();return}\n    nativeCall(()=>CP.App.minimizeApp());\n  }));\n}\n", 1], ["  if(standalone||!location.protocol.startsWith('http'))return;", "  if(standalone||!location.protocol.startsWith('http')||(window.Capacitor&&Capacitor.isNativePlatform&&Capacitor.isNativePlatform()))return;", 1], ["if('serviceWorker' in navigator && location.protocol.startsWith('http')){", "if('serviceWorker' in navigator && location.protocol.startsWith('http') && !(window.Capacitor&&Capacitor.isNativePlatform&&Capacitor.isNativePlatform())){", 1]]
FILES = {"package.json": "{\n  \"name\": \"pixelnaya-smena\",\n  \"version\": \"1.0.0\",\n  \"private\": true,\n  \"description\": \"Pixelnaya Smena: web game packaged for App Store and Google Play with Capacitor\",\n  \"scripts\": {\n    \"prepare:android\": \"bash native/prepare.sh android\",\n    \"prepare:ios\": \"bash native/prepare.sh ios\"\n  },\n  \"dependencies\": {\n    \"@capacitor/android\": \"^8.0.0\",\n    \"@capacitor/app\": \"^8.0.0\",\n    \"@capacitor/core\": \"^8.0.0\",\n    \"@capacitor/haptics\": \"^8.0.0\",\n    \"@capacitor/ios\": \"^8.0.0\",\n    \"@capacitor/preferences\": \"^8.0.0\",\n    \"@capacitor/splash-screen\": \"^8.0.0\",\n    \"@capacitor/status-bar\": \"^8.0.0\"\n  },\n  \"devDependencies\": {\n    \"@capacitor/assets\": \"^3.0.5\",\n    \"@capacitor/cli\": \"^8.0.0\"\n  }\n}\n", "capacitor.config.json": "{\n  \"appId\": \"com.pixelsmena.game\",\n  \"appName\": \"Пиксельная смена\",\n  \"webDir\": \"www\",\n  \"backgroundColor\": \"#9fb6ff\",\n  \"android\": { \"path\": \"native-android\" },\n  \"ios\": { \"path\": \"native-ios\", \"contentInset\": \"never\" },\n  \"plugins\": {\n    \"SplashScreen\": { \"launchShowDuration\": 1200, \"launchAutoHide\": false, \"backgroundColor\": \"#9fb6ff\", \"showSpinner\": false }\n  }\n}\n", "native/assets.py": "# Builds source images for @capacitor/assets from the same drawing code as the site icons.\nimport os\nsrc = open('mkicons.py', encoding='utf-8').read().split('\\nfor S,n,m')[0]\nns = {}\nexec(src, ns)\nicon, Image = ns['icon'], ns['Image']\nos.makedirs('assets', exist_ok=True)\nicon(1024, 0).save('assets/icon-only.png')\nicon(1024, 1).save('assets/icon-foreground.png')\nImage.new('RGB', (1024, 1024), (159, 182, 255)).save('assets/icon-background.png')\ndef splash(path):\n    S = 2732\n    im = Image.new('RGB', (S, S))\n    top, mid, bot = (124, 202, 255), (179, 163, 255), (255, 182, 217)\n    px = im.load()\n    rows = []\n    for y in range(S):\n        t = y / S\n        a, b, k = (top, mid, t / 0.55) if t < 0.55 else (mid, bot, (t - 0.55) / 0.45)\n        rows.append(tuple(int(a[i] + (b[i] - a[i]) * k) for i in range(3)))\n    for y, c in enumerate(rows):\n        im.paste(c, (0, y, S, y + 1))\n    ic = icon(1024, 0).resize((640, 640))\n    im.paste(ic, ((S - 640) // 2, (S - 640) // 2))\n    im.save(path)\nsplash('assets/splash.png')\nsplash('assets/splash-dark.png')\nprint('assets ready')\n", "native/prepare.sh": "#!/usr/bin/env bash\n# Prepares the Capacitor native project for one platform: bash native/prepare.sh android|ios\nset -euo pipefail\nP=\"$1\"\nif [ \"$P\" = android ]; then DIR=native-android; else DIR=native-ios; fi\nnpm install --no-audit --no-fund\nrm -rf www && mkdir -p www\ncp -r index.html manifest.webmanifest icons skin www/\npython3 -m pip install --quiet pillow 2>/dev/null || python3 -m pip install --quiet --break-system-packages pillow\npython3 native/assets.py\n[ -d \"$DIR\" ] || npx cap add \"$P\"\nif [ \"$P\" = android ]; then\n  npx capacitor-assets generate --android --androidProject \"$DIR\" --iconBackgroundColor '#9fb6ff' --splashBackgroundColor '#9fb6ff'\nelse\n  npx capacitor-assets generate --ios --iosProject \"$DIR/App\" --iconBackgroundColor '#9fb6ff' --splashBackgroundColor '#9fb6ff'\nfi\nnpx cap sync \"$P\"\nVC=\"${GITHUB_RUN_NUMBER:-1}\"\nif [ \"$P\" = android ]; then\n  M=\"$DIR/app/src/main/AndroidManifest.xml\"\n  grep -q screenOrientation \"$M\" || sed -i 's/<activity/<activity android:screenOrientation=\"portrait\"/' \"$M\"\n  G=\"$DIR/app/build.gradle\"\n  sed -i -E \"s/versionCode [0-9]+/versionCode $VC/; s/versionName \\\"[^\\\"]*\\\"/versionName \\\"1.0.$VC\\\"/\" \"$G\"\n  grep -E \"versionCode|versionName|targetSdk|compileSdk\" \"$G\" \"$DIR/variables.gradle\" || true\nelse\n  PL=\"$DIR/App/App/Info.plist\"\n  /usr/libexec/PlistBuddy -c \"Delete :UISupportedInterfaceOrientations\" \"$PL\" || true\n  /usr/libexec/PlistBuddy -c \"Add :UISupportedInterfaceOrientations array\" -c \"Add :UISupportedInterfaceOrientations:0 string UIInterfaceOrientationPortrait\" \"$PL\"\n  /usr/libexec/PlistBuddy -c \"Delete :UISupportedInterfaceOrientations~ipad\" \"$PL\" || true\n  /usr/libexec/PlistBuddy -c \"Set :UIRequiresFullScreen true\" \"$PL\" 2>/dev/null || /usr/libexec/PlistBuddy -c \"Add :UIRequiresFullScreen bool true\" \"$PL\"\n  /usr/libexec/PlistBuddy -c \"Set :ITSAppUsesNonExemptEncryption false\" \"$PL\" 2>/dev/null || /usr/libexec/PlistBuddy -c \"Add :ITSAppUsesNonExemptEncryption bool false\" \"$PL\"\n  PB=\"$DIR/App/App.xcodeproj/project.pbxproj\"\n  sed -i '' -E 's/TARGETED_DEVICE_FAMILY = \"1,2\";/TARGETED_DEVICE_FAMILY = 1;/g; s/CURRENT_PROJECT_VERSION = [0-9]+;/CURRENT_PROJECT_VERSION = '\"$VC\"';/g; s/MARKETING_VERSION = [0-9.]+;/MARKETING_VERSION = 1.0;/g' \"$PB\"\n  grep -E \"TARGETED_DEVICE_FAMILY|IPHONEOS_DEPLOYMENT_TARGET|CURRENT_PROJECT_VERSION\" \"$PB\" | sort -u || true\nfi\necho \"prepared $P in $DIR\"\n", ".gitignore": "node_modules/\nwww/\nnative-android/\nnative-ios/\nassets/\nout/\nshots/\n"}
p = 'index.html'
s = open(p, encoding='utf-8').read()
for old, new, cnt in PAIRS:
    assert s.count(old) == cnt, old[:80]
    s = s.replace(old, new)
open(p, 'w', encoding='utf-8').write(s)
for path, body in FILES.items():
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    open(path, 'w', encoding='utf-8').write(body)
os.chmod('native/prepare.sh', 0o755)
print('native shell files written')
